#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Width(pub u16);
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Height(pub u16);

pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(libc::STDOUT_FILENO)
        .or_else(|| terminal_size_of(libc::STDERR_FILENO))
        .or_else(|| terminal_size_of(libc::STDIN_FILENO))
}

pub fn terminal_size_of(fd: std::os::unix::io::RawFd) -> Option<(Width, Height)> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}
EOF
