use std::ffi::CString;
use std::str::FromStr;
use std::time::{Duration, SystemTime};

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SizeKind { Min, Max, Exact }

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SizeConstraint {
    pub kind: SizeKind,
    pub value: u64,
}

impl SizeConstraint {
    pub fn matches(&self, size: u64) -> bool {
        match self.kind {
            SizeKind::Min => size >= self.value,
            SizeKind::Max => size <= self.value,
            SizeKind::Exact => size == self.value,
        }
    }
}

impl FromStr for SizeConstraint {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let err = || format!("'{s}' is not a valid size constraint. See 'fd --help'.");
        let (kind, rest) = if let Some(r) = s.strip_prefix('+') {
            (SizeKind::Min, r)
        } else if let Some(r) = s.strip_prefix('-') {
            (SizeKind::Max, r)
        } else {
            (SizeKind::Exact, s)
        };
        // Split into a leading number and a unit suffix.
        let num_end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
        if num_end == 0 {
            return Err(err());
        }
        let (num_str, unit_str) = rest.split_at(num_end);
        if unit_str.is_empty() {
            return Err(err());
        }
        let num: u64 = num_str.parse().map_err(|_| err())?;
        let unit = unit_str.to_ascii_lowercase();
        let multiplier: u64 = match unit.as_str() {
            "b" => 1,
            "k" | "kb" => 1_000,
            "m" | "mb" => 1_000_000,
            "g" | "gb" => 1_000_000_000,
            "t" | "tb" => 1_000_000_000_000,
            "ki" | "kib" => 1 << 10,
            "mi" | "mib" => 1 << 20,
            "gi" | "gib" => 1 << 30,
            "ti" | "tib" => 1 << 40,
            _ => return Err(err()),
        };
        let value = num.checked_mul(multiplier).ok_or_else(err)?;
        Ok(SizeConstraint { kind, value })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OwnerConstraint {
    pub uid: Option<u32>,
    pub negate_uid: bool,
    pub gid: Option<u32>,
    pub negate_gid: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OwnerFilter(pub OwnerConstraint);

fn lookup_user(name: &str) -> Option<u32> {
    let cname = CString::new(name).ok()?;
    unsafe {
        let pw = libc::getpwnam(cname.as_ptr());
        if pw.is_null() { None } else { Some((*pw).pw_uid as u32) }
    }
}

fn lookup_group(name: &str) -> Option<u32> {
    let cname = CString::new(name).ok()?;
    unsafe {
        let grp = libc::getgrnam(cname.as_ptr());
        if grp.is_null() { None } else { Some((*grp).gr_gid as u32) }
    }
}

fn parse_owner_side(side: &str, is_group: bool) -> Result<Option<(u32, bool)>, String> {
    if side.is_empty() {
        return Ok(None);
    }
    let (negate, name) = if let Some(rest) = side.strip_prefix('!') {
        (true, rest)
    } else {
        (false, side)
    };
    // Try a numeric id first (u32 parsing matches the reference behaviour,
    // including an optional leading '+'). Fall back to name lookup.
    if let Ok(id) = name.parse::<u32>() {
        return Ok(Some((id, negate)));
    }
    let found = if is_group { lookup_group(name) } else { lookup_user(name) };
    match found {
        Some(id) => Ok(Some((id, negate))),
        None => Err(format!(
            "'{}' is not a recognized {} name",
            name,
            if is_group { "group" } else { "user" }
        )),
    }
}

impl FromStr for OwnerFilter {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        if s.matches(':').count() > 1 {
            return Err(format!(
                "more than one ':' present in owner string '{s}'. See 'fd --help'."
            ));
        }
        let (user_part, group_part) = match s.split_once(':') {
            Some((u, g)) => (u, Some(g)),
            None => (s, None),
        };
        let user = parse_owner_side(user_part, false)?;
        let group = match group_part {
            Some(g) => parse_owner_side(g, true)?,
            None => None,
        };
        Ok(OwnerFilter(OwnerConstraint {
            uid: user.map(|(id, _)| id),
            negate_uid: user.map(|(_, n)| n).unwrap_or(false),
            gid: group.map(|(id, _)| id),
            negate_gid: group.map(|(_, n)| n).unwrap_or(false),
        }))
    }
}

// ----- Date / duration parsing (via jiff) -----

fn jiff_timestamp_to_system_time(ts: jiff::Timestamp) -> SystemTime {
    let secs = ts.as_second();
    let nanos = ts.subsec_nanosecond() as u32;
    if secs >= 0 {
        SystemTime::UNIX_EPOCH + Duration::new(secs as u64, nanos)
    } else {
        // number of seconds before epoch; subsec still positive offset from secs second
        let total_nanos_before = (-secs as u64) * 1_000_000_000 - nanos as u64;
        SystemTime::UNIX_EPOCH - Duration::new(total_nanos_before / 1_000_000_000, (total_nanos_before % 1_000_000_000) as u32)
    }
}

pub fn parse_date_or_duration(input: &str) -> Option<SystemTime> {
    // @timestamp form
    if let Some(rest) = input.strip_prefix('@') {
        if let Ok(secs) = rest.parse::<u64>() {
            return Some(SystemTime::UNIX_EPOCH + Duration::from_secs(secs));
        }
        return None;
    }
    // Zoned datetime (with time zone annotation)
    if let Ok(zoned) = input.parse::<jiff::Zoned>() {
        return Some(jiff_timestamp_to_system_time(zoned.timestamp()));
    }
    // Timestamp (with offset)
    if let Ok(ts) = input.parse::<jiff::Timestamp>() {
        return Some(jiff_timestamp_to_system_time(ts));
    }
    // Civil datetime (or date) interpreted in the system time zone
    if let Ok(dt) = input.parse::<jiff::civil::DateTime>() {
        if let Ok(zoned) = dt.to_zoned(jiff::tz::TimeZone::system()) {
            return Some(jiff_timestamp_to_system_time(zoned.timestamp()));
        }
        return None;
    }
    // Duration / span relative to now
    if let Ok(span) = input.parse::<jiff::Span>() {
        let now = jiff::Zoned::now();
        if let Ok(threshold) = now.checked_sub(span) {
            return Some(jiff_timestamp_to_system_time(threshold.timestamp()));
        }
        return None;
    }
    None
}
