use std::collections::HashMap;
use std::ffi::{OsStr};
use std::fs::Metadata;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::{FileTypeExt, MetadataExt};
use std::path::Path;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Ansi(u8), // foreground 30-37, background 40-47 (stored full code)
    Fixed(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Style {
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
    pub foreground: Option<Color>,
    pub background: Option<Color>,
}

impl Style {
    pub fn is_plain(&self) -> bool {
        !self.bold
            && !self.dimmed
            && !self.italic
            && !self.underline
            && !self.blink
            && !self.reverse
            && !self.hidden
            && !self.strikethrough
            && self.foreground.is_none()
            && self.background.is_none()
    }

    fn prefix(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.bold { parts.push("1".into()); }
        if self.dimmed { parts.push("2".into()); }
        if self.italic { parts.push("3".into()); }
        if self.underline { parts.push("4".into()); }
        if self.blink { parts.push("5".into()); }
        if self.reverse { parts.push("7".into()); }
        if self.hidden { parts.push("8".into()); }
        if self.strikethrough { parts.push("9".into()); }
        if let Some(bg) = self.background {
            parts.push(match bg {
                Color::Ansi(c) => c.to_string(),
                Color::Fixed(n) => format!("48;5;{n}"),
                Color::Rgb(r, g, b) => format!("48;2;{r};{g};{b}"),
            });
        }
        if let Some(fg) = self.foreground {
            parts.push(match fg {
                Color::Ansi(c) => c.to_string(),
                Color::Fixed(n) => format!("38;5;{n}"),
                Color::Rgb(r, g, b) => format!("38;2;{r};{g};{b}"),
            });
        }
        if parts.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", parts.join(";"))
        }
    }

    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            text.to_owned()
        } else {
            format!("{}{}\x1b[0m", self.prefix(), text)
        }
    }

    pub fn from_ansi_codes(input: &str) -> Option<Style> {
        if input.is_empty() {
            return None;
        }
        // Parse each ;-separated component, taking the part before any ':'.
        let mut codes: Vec<u8> = Vec::new();
        for part in input.split(';') {
            let first = part.split(':').next()?;
            if first.is_empty() {
                return None;
            }
            codes.push(first.parse::<u8>().ok()?);
        }
        if codes.iter().all(|&c| c == 0) {
            return None;
        }
        let mut style = Style::default();
        let mut i = 0usize;
        while i < codes.len() {
            let code = codes[i];
            i += 1;
            match code {
                0 => {
                    style.bold = false;
                    style.dimmed = false;
                    style.italic = false;
                    style.underline = false;
                    style.blink = false;
                    style.reverse = false;
                    style.hidden = false;
                    style.strikethrough = false;
                }
                1 => style.bold = true,
                2 => style.dimmed = true,
                3 => style.italic = true,
                4 => style.underline = true,
                5 | 6 => style.blink = true,
                7 => style.reverse = true,
                8 => style.hidden = true,
                9 => style.strikethrough = true,
                22 => {
                    style.bold = false;
                    style.dimmed = false;
                }
                23 => style.italic = false,
                24 => style.underline = false,
                25 => style.blink = false,
                27 => style.reverse = false,
                28 => style.hidden = false,
                29 => style.strikethrough = false,
                30..=37 => style.foreground = Some(Color::Ansi(code)),
                38 | 48 | 58 => {
                    // extended colour
                    if i >= codes.len() {
                        return None;
                    }
                    let mode = codes[i];
                    i += 1;
                    let color = match mode {
                        5 => {
                            if i >= codes.len() { return None; }
                            let n = codes[i];
                            i += 1;
                            Color::Fixed(n)
                        }
                        2 => {
                            if i + 2 >= codes.len() { return None; }
                            let (r, g, b) = (codes[i], codes[i + 1], codes[i + 2]);
                            i += 3;
                            Color::Rgb(r, g, b)
                        }
                        _ => return None,
                    };
                    match code {
                        38 => style.foreground = Some(color),
                        48 => style.background = Some(color),
                        _ => { /* underline colours are ignored when rendering */ }
                    }
                }
                39 => style.foreground = None,
                40..=47 => style.background = Some(Color::Ansi(code)),
                49 => style.background = None,
                90..=97 => style.foreground = Some(Color::Fixed(code - 90 + 8)),
                100..=107 => style.background = Some(Color::Fixed(code - 100 + 8)),
                _ => { /* other codes are accepted but have no effect */ }
            }
        }
        Some(style)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Indicator {
    Directory,
    SymbolicLink,
    SymbolicLinkOrphan,
    ExecutableFile,
    RegularFile,
    NamedPipe,
    Socket,
    BlockDevice,
    CharDevice,
    Setuid,
    Setgid,
    Capability,
    Sticky,
    OtherWritable,
    StickyOtherWritable,
    MultipleHardLinks,
}

pub struct LsColors {
    indicators: HashMap<Indicator, Option<Style>>,
    // (lower-cased suffix (after '*'), style) in the order given
    suffixes: Vec<(String, Option<Style>)>,
    filenames: HashMap<String, Option<Style>>,
    // set when ln=target appears in LS_COLORS
    symlink_target: bool,
}

fn default_indicator_styles() -> HashMap<Indicator, Option<Style>> {
    let mut m = HashMap::new();
    let s = |code: &str| Style::from_ansi_codes(code);
    m.insert(Indicator::Directory, s("01;34"));
    m.insert(Indicator::SymbolicLink, s("01;36"));
    m.insert(Indicator::ExecutableFile, s("01;32"));
    m.insert(Indicator::NamedPipe, s("33"));
    m.insert(Indicator::Socket, s("01;35"));
    m.insert(Indicator::BlockDevice, s("01;33"));
    m.insert(Indicator::CharDevice, s("01;33"));
    m.insert(Indicator::Sticky, s("37;44"));
    m.insert(Indicator::OtherWritable, s("34;42"));
    m.insert(Indicator::StickyOtherWritable, s("30;42"));
    m.insert(Indicator::Setuid, s("37;41"));
    m.insert(Indicator::Setgid, s("30;43"));
    m.insert(Indicator::Capability, s("30;41"));
    m
}

impl LsColors {
    pub fn from_env() -> Self {
        match std::env::var_os("LS_COLORS") {
            Some(val) => {
                let text = val.to_string_lossy().into_owned();
                let mut lc = LsColors {
                    indicators: default_indicator_styles(),
                    suffixes: Vec::new(),
                    filenames: HashMap::new(),
                    symlink_target: false,
                };
                lc.parse_lscolors(&text);
                lc
            }
            None => Self::default_theme(),
        }
    }

    fn parse_lscolors(&mut self, text: &str) {
        for entry in text.split(':') {
            if entry.is_empty() {
                continue;
            }
            let Some((key, value)) = entry.split_once('=') else { continue };
            if key == "ln" && value == "target" {
                self.symlink_target = true;
                self.indicators.insert(Indicator::SymbolicLink, None);
                continue;
            }
            let style = Style::from_ansi_codes(value);
            if let Some(ind) = indicator_from_code(key) {
                self.indicators.insert(ind, style);
            } else if let Some(suffix) = key.strip_prefix('*') {
                self.suffixes
                    .push((suffix.to_lowercase(), style));
            } else {
                // Keys that are neither indicators nor '*'-patterns
                // (e.g. lc/rc/ec or unknown codes) are ignored.
            }
        }
    }

    pub fn indicator_style(&self, ind: Indicator) -> Option<Style> {
        self.indicators.get(&ind).copied().flatten()
    }

    pub fn directory_style(&self) -> Option<Style> {
        self.indicator_style(Indicator::Directory)
    }

    pub fn style_for_path(&self, path: &Path, metadata: Option<&Metadata>) -> Option<Style> {
        let owned_meta;
        let md = match metadata {
            Some(m) => Some(m.clone()),
            None => {
                owned_meta = std::fs::symlink_metadata(path).ok();
                owned_meta
            }
        };
        let md_ref = md.as_ref();

        if let Some(md) = md_ref {
            let ft = md.file_type();
            let mode = md.mode();
            if ft.is_symlink() {
                if !path.exists() {
                    // orphaned link: use or= style if set, else fall back to ln=
                    if let Some(s) = self.indicator_style(Indicator::SymbolicLinkOrphan) {
                        return Some(s);
                    }
                    if self.symlink_target {
                        // ln=target with an explicitly empty or= still falls back above;
                        // if no orphan style at all, fall through to ln handling
                        if self.indicators.contains_key(&Indicator::SymbolicLinkOrphan) {
                            return self.indicator_style(Indicator::SymbolicLink);
                        }
                        return self.indicator_style(Indicator::SymbolicLink);
                    }
                    return self.indicator_style(Indicator::SymbolicLink);
                }
                if self.symlink_target {
                    return None;
                }
                return self.indicator_style(Indicator::SymbolicLink);
            }
            if ft.is_dir() {
                let sticky = mode & 0o1000 != 0;
                let other_writable = mode & 0o002 != 0;
                let ind = if sticky && other_writable {
                    Indicator::StickyOtherWritable
                } else if sticky {
                    Indicator::Sticky
                } else if other_writable {
                    Indicator::OtherWritable
                } else {
                    Indicator::Directory
                };
                if ind != Indicator::Directory {
                    if let Some(s) = self.indicator_style(ind) {
                        return Some(s);
                    }
                    // fall through to the plain directory style
                }
                return self.indicator_style(Indicator::Directory);
            }
            if ft.is_fifo() {
                return self.indicator_style(Indicator::NamedPipe);
            }
            if ft.is_socket() {
                return self.indicator_style(Indicator::Socket);
            }
            if ft.is_block_device() {
                return self.indicator_style(Indicator::BlockDevice);
            }
            if ft.is_char_device() {
                return self.indicator_style(Indicator::CharDevice);
            }
            if ft.is_file() {
                if mode & 0o4000 != 0 {
                    if let Some(s) = self.indicator_style(Indicator::Setuid) {
                        return Some(s);
                    }
                }
                if mode & 0o2000 != 0 {
                    if let Some(s) = self.indicator_style(Indicator::Setgid) {
                        return Some(s);
                    }
                }
                if has_capability(path) {
                    if let Some(s) = self.indicator_style(Indicator::Capability) {
                        return Some(s);
                    }
                }
                if mode & 0o111 != 0 {
                    if let Some(s) = self.indicator_style(Indicator::ExecutableFile) {
                        return Some(s);
                    }
                }
                if md.nlink() > 1 {
                    if let Some(s) = self.indicator_style(Indicator::MultipleHardLinks) {
                        return Some(s);
                    }
                }
            }
        }

        // Regular files (or unknown metadata): exact filename, then suffix.
        let file_name_os: &OsStr = match path.file_name() {
            Some(n) => n,
            None => path.as_os_str(),
        };
        let file_name = match file_name_os.to_str() {
            Some(s) => s,
            None => return self.indicator_style(Indicator::RegularFile),
        };
        if let Some(s) = self.filenames.get(file_name) {
            if s.is_some() {
                return *s;
            }
        }
        let lower = file_name.to_lowercase();
        // The last matching suffix in LS_COLORS order wins.
        for (suffix, style) in self.suffixes.iter().rev() {
            if lower.ends_with(suffix.as_str()) {
                return *style;
            }
        }
        self.indicator_style(Indicator::RegularFile)
    }
}

fn has_capability(path: &Path) -> bool {
    use std::os::unix::ffi::OsStrExt as _;
    let Ok(cpath) = std::ffi::CString::new(path.as_os_str().as_bytes()) else { return false };
    let Ok(cname) = std::ffi::CString::new("security.capability") else { return false };
    unsafe {
        let n = libc::getxattr(
            cpath.as_ptr(),
            cname.as_ptr(),
            std::ptr::null_mut(),
            0,
        );
        n > 0
    }
}

fn indicator_from_code(code: &str) -> Option<Indicator> {
    Some(match code {
        "di" => Indicator::Directory,
        "ln" => Indicator::SymbolicLink,
        "or" => Indicator::SymbolicLinkOrphan,
        "ex" => Indicator::ExecutableFile,
        "fi" => Indicator::RegularFile,
        "pi" => Indicator::NamedPipe,
        "so" => Indicator::Socket,
        "bd" => Indicator::BlockDevice,
        "cd" => Indicator::CharDevice,
        "su" => Indicator::Setuid,
        "sg" => Indicator::Setgid,
        "ca" => Indicator::Capability,
        "st" => Indicator::Sticky,
        "ow" => Indicator::OtherWritable,
        "tw" => Indicator::StickyOtherWritable,
        "mh" => Indicator::MultipleHardLinks,
        _ => return None,
    })
}

impl LsColors {
    fn default_theme() -> Self {
        // The built-in theme used when LS_COLORS is not set at all.
        let mut m: HashMap<Indicator, Option<Style>> = HashMap::new();
        let s = |code: &str| Style::from_ansi_codes(code);
        m.insert(Indicator::Directory, s("38;5;81"));
        m.insert(Indicator::SymbolicLink, s("38;5;203"));
        m.insert(Indicator::SymbolicLinkOrphan, s("48;5;203;38;5;16"));
        m.insert(Indicator::ExecutableFile, s("1;38;5;203"));
        m.insert(Indicator::NamedPipe, s("48;5;81;38;5;16"));
        m.insert(Indicator::Socket, s("48;5;203;38;5;16"));
        m.insert(Indicator::BlockDevice, s("48;5;81;38;5;16"));
        m.insert(Indicator::CharDevice, s("48;5;81;38;5;16"));
        m.insert(Indicator::Sticky, s("48;5;81;38;5;16"));
        m.insert(Indicator::OtherWritable, s("48;5;81;38;5;16"));
        m.insert(Indicator::StickyOtherWritable, s("48;5;81;38;5;16"));
        m.insert(Indicator::Setuid, s("48;5;203;38;5;16"));
        m.insert(Indicator::Setgid, s("48;5;203;38;5;16"));
        m.insert(Indicator::Capability, s("48;5;203;38;5;16"));

        let mut lc = LsColors {
            indicators: m,
            suffixes: Vec::new(),
            filenames: HashMap::new(),
            symlink_target: false,
        };
        lc.load_default_suffixes();
        lc
    }

    fn load_default_suffixes(&mut self) {
        for (suffix, code) in crate::default_colors::DEFAULT_SUFFIX_STYLES {
            self.suffixes
                .push((suffix.to_string(), Style::from_ansi_codes(code)));
        }
        for (name, code) in crate::default_colors::DEFAULT_FILENAME_STYLES {
            self.filenames
                .insert(name.to_string(), Style::from_ansi_codes(code));
        }
    }
}

// re-export for convenience
pub fn os_bytes(s: &OsStr) -> &[u8] {
    s.as_bytes()
}
