    pub fn from_ansi_codes(input: &str) -> Option<Style> {
        if input.is_empty() {
            return None;
        }
        // Parse each ;-separated component, taking the part before any ':'.
        let mut codes: Vec<u8> = Vec::new();
        for part in input.split(';') {
            let first = part.split(':').next()?;
            if first.is_empty() {
                return None;
            }
            codes.push(first.parse::<u8>().ok()?);
        }
        if codes.iter().all(|&c| c == 0) {
            return None;
        }
        let mut style = Style::default();
        let mut i = 0usize;
        while i < codes.len() {
            let code = codes[i];
            i += 1;
            match code {
                0 => {
                    style.bold = false;
                    style.dimmed = false;
                    style.italic = false;
                    style.underline = false;
                    style.blink = false;
                    style.reverse = false;
                    style.hidden = false;
                    style.strikethrough = false;
                }
                1 => style.bold = true,
                2 => style.dimmed = true,
                3 => style.italic = true,
                4 => style.underline = true,
                5 | 6 => style.blink = true,
                7 => style.reverse = true,
                8 => style.hidden = true,
                9 => style.strikethrough = true,
                22 => {
                    style.bold = false;
                    style.dimmed = false;
                }
                23 => style.italic = false,
                24 => style.underline = false,
                25 => style.blink = false,
                27 => style.reverse = false,
                28 => style.hidden = false,
                29 => style.strikethrough = false,
                30..=37 => style.foreground = Some(Color::Ansi(code)),
                38 | 48 | 58 => {
                    // extended colour
                    if i >= codes.len() {
                        return None;
                    }
                    let mode = codes[i];
                    i += 1;
                    let color = match mode {
                        5 => {
                            if i >= codes.len() { return None; }
                            let n = codes[i];
                            i += 1;
                            Color::Fixed(n)
                        }
                        2 => {
                            if i + 2 >= codes.len() { return None; }
                            let (r, g, b) = (codes[i], codes[i + 1], codes[i + 2]);
                            i += 3;
                            Color::Rgb(r, g, b)
                        }
                        _ => return None,
                    };
                    match code {
                        38 => style.foreground = Some(color),
                        48 => style.background = Some(color),
                        _ => { /* underline colours are ignored when rendering */ }
                    }
                }
                39 => style.foreground = None,
                40..=47 => style.background = Some(Color::Ansi(code)),
                49 => style.background = None,
                90..=97 => style.foreground = Some(Color::Fixed(code - 90 + 8)),
                100..=107 => style.background = Some(Color::Fixed(code - 100 + 8)),
                _ => { /* other codes are accepted but have no effect */ }
            }
        }
        Some(style)
    }
}

