{"command":"cat > src/exec.rs <<'RUST'
use std::ffi::{OsStr, OsString};
use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Placeholder {
    Path,
    Basename,
    Parent,
    PathNoExt,
    BasenameNoExt,
}

#[derive(Clone, Debug)]
pub enum Token {
    Text(String),
    Placeholder(Placeholder),
}

pub fn parse_template(input: &str) -> Vec<Token> {
    let mut tokens: Vec<Token> = Vec::new();
    let push_text = |tokens: &mut Vec<Token>, text: &str| {
        if text.is_empty() {
            return;
        }
        if let Some(Token::Text(prev)) = tokens.last_mut() {
            prev.push_str(text);
        } else {
            tokens.push(Token::Text(text.to_owned()));
        }
    };

    for (i, segment) in input.split("{{").enumerate() {
        if i > 0 {
            push_text(&mut tokens, "{");
        }
        for (j, segment2) in segment.split("}}").enumerate() {
            if j > 0 {
                push_text(&mut tokens, "}");
            }
            parse_placeholders(segment2, &mut tokens, &push_text);
        }
    }
    tokens
}

fn parse_placeholders(
    mut segment: &str,
    tokens: &mut Vec<Token>,
    push_text: &dyn Fn(&mut Vec<Token>, &str),
) {
    const PATTERNS: &[(&str, Placeholder)] = &[
        ("{/.}", Placeholder::BasenameNoExt),
        ("{//}", Placeholder::Parent),
        ("{/}", Placeholder::Basename),
        ("{.}", Placeholder::PathNoExt),
        ("{}", Placeholder::Path),
    ];
    while !segment.is_empty() {
        let mut best: Option<(usize, &'static str, Placeholder)> = None;
        for (pat, kind) in PATTERNS {
            if let Some(pos) = segment.find(pat) {
                let replace = match best {
                    None => true,
                    Some((bp, bpat, _)) => pos < bp || (pos == bp && pat.len() > bpat.len()),
                };
                if replace {
                    best = Some((pos, pat, *kind));
                }
            }
        }
        match best {
            None => {
                push_text(tokens, segment);
                break;
            }
            Some((pos, pat, kind)) => {
                if pos > 0 {
                    push_text(tokens, &segment[..pos]);
                }
                tokens.push(Token::Placeholder(kind));
                segment = &segment[pos + pat.len()..];
            }
        }
    }
}

pub fn tokens_have_placeholder(tokens: &[Token]) -> bool {
    tokens.iter().any(|t| matches!(t, Token::Placeholder(_)))
}

#[derive(Clone, Debug)]
pub struct CommandTemplate {
    pub args: Vec<Vec<Token>>,
    pub has_placeholder: bool,
}

impl CommandTemplate {
    pub fn new(raw_args: Vec<String>) -> Self {
        let args: Vec<Vec<Token>> = raw_args.iter().map(|a| parse_template(a)).collect();
        let has_placeholder = args.iter().any(|a| tokens_have_placeholder(a));
        Self { args, has_placeholder }
    }

    fn build_arg(&self, tokens: &[Token], values: &PlaceholderValues) -> OsString {
        let mut out = OsString::new();
        for token in tokens {
            match token {
                Token::Text(text) => out.push(text),
                Token::Placeholder(kind) => out.push(values.get(*kind)),
            }
        }
        out
    }

    pub fn build_args_for_entry(&self, values: &PlaceholderValues) -> Vec<OsString> {
        let mut args: Vec<OsString> =
            self.args.iter().map(|a| self.build_arg(a, values)).collect();
        if !self.has_placeholder {
            args.push(values.path.clone());
        }
        args
    }
}

#[derive(Clone, Debug)]
pub struct PlaceholderValues {
    pub path: OsString,
    pub basename: OsString,
    pub parent: OsString,
    pub path_no_ext: OsString,
    pub basename_no_ext: OsString,
}

impl PlaceholderValues {
    pub fn get(&self, kind: Placeholder) -> &OsStr {
        match kind {
            Placeholder::Path => &self.path,
            Placeholder::Basename => &self.basename,
            Placeholder::Parent => &self.parent,
            Placeholder::PathNoExt => &self.path_no_ext,
            Placeholder::BasenameNoExt => &self.basename_no_ext,
        }
    }

    pub fn new(display_path: &Path, path_separator: Option<&str>) -> Self {
        let path_buf = display_path.to_path_buf();
        let basename: OsString = display_path
            .file_name()
            .map(|s| s.to_owned())
            .unwrap_or_else(|| display_path.as_os_str().to_owned());
        let parent: OsString = match display_path.parent() {
            Some(p) if !p.as_os_str().is_empty() => p.as_os_str().to_owned(),
            _ => OsString::from("."),
        };
        let stem: OsString = display_path
            .file_stem()
            .map(|s| s.to_owned())
            .unwrap_or_else(|| basename.clone());
        let parent_for_noext = display_path.parent().unwrap_or(Path::new(""));
        let joined = parent_for_noext.join(&stem);
        let path_no_ext: PathBuf = match joined.strip_prefix(".") {
            Ok(stripped) => stripped.to_path_buf(),
            Err(_) => joined,
        };
        let basename_no_ext: OsString = Path::new(&stem)
            .file_name()
            .map(|s| s.to_owned())
            .unwrap_or_default();

        let convert = |value: OsString| -> OsString {
            match path_separator {
                Some(sep) => {
                    let text = value.to_string_lossy().replace('/', sep);
                    OsString::from(text)
                }
                None => value,
            }
        };

        Self {
            path: convert(path_buf.as_os_str().to_owned()),
            basename: basename.clone(),
            parent: convert(parent),
            path_no_ext: convert(path_no_ext.as_os_str().to_owned()),
            basename_no_ext,
        }
    }
}

pub struct CommandSet {
    pub commands: Vec<CommandTemplate>,
    pub batch: bool,
}

pub enum ExecOutcome {
    Success,
    // A command ran but returned a non-success status.
    NonZero,
    // A command could not be spawned.
    SpawnError,
}

pub fn execute_command(args: &[OsString]) -> ExecOutcome {
    if args.is_empty() {
        return ExecOutcome::Success;
    }
    let program = &args[0];
    match Command::new(program).args(&args[1..]).status() {
        Ok(status) => {
            if status.success() {
                ExecOutcome::Success
            } else {
                ExecOutcome::NonZero
            }
        }
        Err(err) => {
            if err.kind() == std::io::ErrorKind::NotFound {
                eprintln!("[fd error]: Command not found: {}", program.to_string_lossy());
            } else {
                eprintln!("[fd error]: Problem while executing command: {err}");
            }
            ExecOutcome::SpawnError
        }
    }
}

fn arg_cost(arg: &OsStr) -> usize {
    arg.as_bytes().len() + 1 + std::mem::size_of::<usize>()
}

fn max_command_length() -> usize {
    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    let arg_max = if arg_max > 0 { arg_max as usize } else { 131_072 };
    let env_cost: usize = std::env::vars_os()
        .map(|(k, v)| k.as_bytes().len() + 1 + v.as_bytes().len() + 1 + std::mem::size_of::<usize>())
        .sum();
    arg_max.saturating_sub(env_cost + 6144)
}

pub fn execute_batch(
    commands: &[CommandTemplate],
    entries: &[crate::EntryData],
    batch_size: usize,
    path_separator: Option<&str>,
    display_path_fn: &dyn Fn(&crate::EntryData) -> PathBuf,
) -> bool {
    // Returns true if any error happened.
    let mut had_error = false;
    if entries.is_empty() {
        return false;
    }
    let max_len = max_command_length();

    'commands: for template in commands {
        // Build the values for every entry once.
        let all_values: Vec<PlaceholderValues> = entries
            .iter()
            .map(|e| PlaceholderValues::new(&display_path_fn(e), path_separator))
            .collect();

        // Split into batches obeying batch_size and the OS argument limit.
        let mut start = 0usize;
        while start < all_values.len() {
            // Build a batch greedily.
            let mut batch_end = start;
            let mut current_cost: usize = 0;
            // Cost of the fixed arguments (approximation: cost of each non-expanded arg).
            // We compute costs incrementally below once we know the shape.
            let placeholder_arg_index = template
                .args
                .iter()
                .position(|a| tokens_have_placeholder(a));

            let fixed_cost: usize = template
                .args
                .iter()
                .enumerate()
                .filter(|(idx, _)| Some(*idx) != placeholder_arg_index)
                .map(|(_, a)| {
                    // cost of the rendered fixed argument
                    let rendered = template.build_arg(a, &all_values[start]);
                    arg_cost(&rendered)
                })
                .sum();
            current_cost += fixed_cost;

            while batch_end < all_values.len() {
                let entry_cost = match placeholder_arg_index {
                    Some(idx) => {
                        let rendered = template.build_arg(&template.args[idx], &all_values[batch_end]);
                        arg_cost(&rendered)
                    }
                    None => arg_cost(&all_values[batch_end].path),
                };
                if batch_end > start {
                    if batch_size > 0 && batch_end - start >= batch_size {
                        break;
                    }
                    if current_cost + entry_cost > max_len {
                        break;
                    }
                }
                current_cost += entry_cost;
                batch_end += 1;
                if batch_size > 0 && batch_end - start >= batch_size {
                    break;
                }
            }
            if batch_end == start {
                batch_end = start + 1;
            }

            // Build final argument list for this batch.
            let mut argv: Vec<OsString> = Vec::new();
            match placeholder_arg_index {
                None => {
                    for a in &template.args {
                        argv.push(template.build_arg(a, &all_values[start]));
                    }
                    for value in &all_values[start..batch_end] {
                        argv.push(value.path.clone());
                    }
                }
                Some(idx) => {
                    for (i, a) in template.args.iter().enumerate() {
                        if i == idx {
                            for value in &all_values[start..batch_end] {
                                argv.push(template.build_arg(a, value));
                            }
                        } else {
                            argv.push(template.build_arg(a, &all_values[start]));
                        }
                    }
                }
            }

            match execute_command(&argv) {
                ExecOutcome::Success => {}
                ExecOutcome::NonZero => {
                    had_error = true;
                }
                ExecOutcome::SpawnError => {
                    had_error = true;
                    break 'commands;
                }
            }
            start = batch_end;
        }
    }
    had_error
}

pub fn execute_each(
    commands: &[CommandTemplate],
    entries: &[crate::EntryData],
    threads: usize,
    print0: bool,
    path_separator: Option<&str>,
    display_path_fn: &(dyn Fn(&crate::EntryData) -> PathBuf + Sync),
) -> bool {
    let had_error = AtomicBool::new(false);
    let next_index = AtomicUsize::new(0);
    let worker_count = threads.max(1).min(entries.len().max(1)).min(256);

    let run_one = |entry: &crate::EntryData, had_error: &AtomicBool| {
        let values = PlaceholderValues::new(&display_path_fn(entry), path_separator);
        for template in commands {
            let argv = template.build_args_for_entry(&values);
            match execute_command(&argv) {
                ExecOutcome::Success => {}
                ExecOutcome::NonZero | ExecOutcome::SpawnError => {
                    had_error.store(true, Ordering::Relaxed);
                    break;
                }
            }
        }
        if print0 {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(&[0]);
            let _ = out.flush();
        }
    };

    if worker_count <= 1 || entries.len() <= 1 {
        for entry in entries {
            run_one(entry, &had_error);
        }
    } else {
        std::thread::scope(|scope| {
            for _ in 0..worker_count {
                scope.spawn(|| loop {
                    let idx = next_index.fetch_add(1, Ordering::Relaxed);
                    if idx >= entries.len() {
                        break;
                    }
                    run_one(&entries[idx], &had_error);
                });
            }
        });
    }
    had_error.load(Ordering::Relaxed)
}
RUST"}

