}

pub enum ExecOutcome {
    Success,
    // A command ran but returned a non-success status.
    NonZero,
    // A command could not be spawned.
    SpawnError,
}

pub fn execute_command(args: &[OsString]) -> ExecOutcome {
    if args.is_empty() {
        return ExecOutcome::Success;
    }
    let program = &args[0];
    match Command::new(program).args(&args[1..]).status() {
        Ok(status) => {
            if status.success() {
                ExecOutcome::Success
            } else {
                ExecOutcome::NonZero
            }
        }
        Err(err) => {
