fn arg_cost(arg: &OsStr) -> usize {
    arg.as_bytes().len() + 1 + std::mem::size_of::<usize>()
}

fn max_command_length() -> usize {
    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    let arg_max = if arg_max > 0 { arg_max as usize } else { 131_072 };
    let env_cost: usize = std::env::vars_os()
        .map(|(k, v)| k.as_bytes().len() + 1 + v.as_bytes().len() + 1 + std::mem::size_of::<usize>())
        .sum();
    arg_max.saturating_sub(env_cost + 6144)
}

pub fn execute_batch(
    commands: &[CommandTemplate],
    entries: &[crate::EntryData],
    batch_size: usize,
    path_separator: Option<&str>,
    display_path_fn: &dyn Fn(&crate::EntryData) -> PathBuf,
) -> bool {
    // Returns true if any error happened.
    let mut had_error = false;
    if entries.is_empty() {
        return false;
    }
    let max_len = max_command_length();

    'commands: for template in commands {
        // Build the values for every entry once.
        let all_values: Vec<PlaceholderValues> = entries
            .iter()
            .map(|e| PlaceholderValues::new(&display_path_fn(e), path_separator))
            .collect();

        // Split into batches obeying batch_size and the OS argument limit.
        let mut start = 0usize;
        while start < all_values.len() {
            // Build a batch greedily.
            let mut batch_end = start;
            let mut current_cost: usize = 0;
            // Cost of the fixed arguments (approximation: cost of each non-expanded arg).
            // We compute costs incrementally below once we know the shape.
            let placeholder_arg_index = template
                .args
                .iter()
                .position(|a| tokens_have_placeholder(a));

            let fixed_cost: usize = template
                .args
                .iter()
                .enumerate()
                .filter(|(idx, _)| Some(*idx) != placeholder_arg_index)
                .map(|(_, a)| {
                    // cost of the rendered fixed argument
                    let rendered = template.build_arg(a, &all_values[start]);
                    arg_cost(&rendered)
                })
                .sum();
            current_cost += fixed_cost;

            while batch_end < all_values.len() {
                let entry_cost = match placeholder_arg_index {
                    Some(idx) => {
                        let rendered = template.build_arg(&template.args[idx], &all_values[batch_end]);
                        arg_cost(&rendered)
                    }
                    None => arg_cost(&all_values[batch_end].path),
                };
                if batch_end > start {
                    if batch_size > 0 && batch_end - start >= batch_size {
                        break;
                    }
                    if current_cost + entry_cost > max_len {
                        break;
                    }
                }
                current_cost += entry_cost;
                batch_end += 1;
                if batch_size > 0 && batch_end - start >= batch_size {
                    break;
                }
            }
            if batch_end == start {
                batch_end = start + 1;
            }

            // Build final argument list for this batch.
            let mut argv: Vec<OsString> = Vec::new();
            match placeholder_arg_index {
                None => {
                    for a in &template.args {
                        argv.push(template.build_arg(a, &all_values[start]));
                    }
                    for value in &all_values[start..batch_end] {
                        argv.push(value.path.clone());
                    }
                }
                Some(idx) => {
                    for (i, a) in template.args.iter().enumerate() {
                        if i == idx {
                            for value in &all_values[start..batch_end] {
                                argv.push(template.build_arg(a, value));
                            }
                        } else {
                            argv.push(template.build_arg(a, &all_values[start]));
                        }
                    }
                }
            }

            match execute_command(&argv) {
                ExecOutcome::Success => {}
                ExecOutcome::NonZero => {
                    had_error = true;
                }
                ExecOutcome::SpawnError => {
                    had_error = true;
                    break 'commands;
                }
            }
            start = batch_end;
        }
    }
    had_error
}

pub fn execute_each(
    commands: &[CommandTemplate],
    entries: &[crate::EntryData],
    threads: usize,
    print0: bool,
    path_separator: Option<&str>,
    display_path_fn: &(dyn Fn(&crate::EntryData) -> PathBuf + Sync),
) -> bool {
    let had_error = AtomicBool::new(false);
    let next_index = AtomicUsize::new(0);
    let worker_count = threads.max(1).min(entries.len().max(1)).min(256);

    let run_one = |entry: &crate::EntryData, had_error: &AtomicBool| {
        let values = PlaceholderValues::new(&display_path_fn(entry), path_separator);
        for template in commands {
            let argv = template.build_args_for_entry(&values);
            match execute_command(&argv) {
                ExecOutcome::Success => {}
                ExecOutcome::NonZero | ExecOutcome::SpawnError => {
                    had_error.store(true, Ordering::Relaxed);
                    break;
                }
            }
        }
        if print0 {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(&[0]);
            let _ = out.flush();
        }
    };

    if worker_count <= 1 || entries.len() <= 1 {
        for entry in entries {
            run_one(entry, &had_error);
        }
    } else {
        std::thread::scope(|scope| {
            for _ in 0..worker_count {
                scope.spawn(|| loop {
                    let idx = next_index.fetch_add(1, Ordering::Relaxed);
                    if idx >= entries.len() {
                        break;
                    }
                    run_one(&entries[idx], &had_error);
                });
            }
        });
    }
    had_error.load(Ordering::Relaxed)
}
