use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Placeholder {
    Path,
    Basename,
    Parent,
    PathNoExt,
    BasenameNoExt,
}

#[derive(Clone, Debug)]
pub enum Token {
    Text(String),
    Placeholder(Placeholder),
}

pub fn parse_template(input: &str) -> Vec<Token> {
    let mut tokens: Vec<Token> = Vec::new();
    let push_text = |tokens: &mut Vec<Token>, text: &str| {
        if text.is_empty() {
            return;
        }
        if let Some(Token::Text(prev)) = tokens.last_mut() {
            prev.push_str(text);
        } else {
            tokens.push(Token::Text(text.to_owned()));
        }
    };

    for (i, segment) in input.split("{{").enumerate() {
        if i > 0 {
            push_text(&mut tokens, "{");
        }
        for (j, segment2) in segment.split("}}").enumerate() {
            if j > 0 {
                push_text(&mut tokens, "}");
            }
            parse_placeholders(segment2, &mut tokens, &push_text);
        }
    }
    tokens
}

fn parse_placeholders(
    mut segment: &str,
    tokens: &mut Vec<Token>,
    push_text: &dyn Fn(&mut Vec<Token>, &str),
) {
    const PATTERNS: &[(&str, Placeholder)] = &[
        ("{/.}", Placeholder::BasenameNoExt),
        ("{//}", Placeholder::Parent),
        ("{/}", Placeholder::Basename),
        ("{.}", Placeholder::PathNoExt),
        ("{}", Placeholder::Path),
    ];
    while !segment.is_empty() {
        let mut best: Option<(usize, &'static str, Placeholder)> = None;
        for (pat, kind) in PATTERNS {
            if let Some(pos) = segment.find(pat) {
                let replace = match best {
                    None => true,
                    Some((bp, bpat, _)) => pos < bp || (pos == bp && pat.len() > bpat.len()),
                };
                if replace {
                    best = Some((pos, pat, *kind));
                }
            }
        }
        match best {
            None => {
                push_text(tokens, segment);
                break;
            }
            Some((pos, pat, kind)) => {
                if pos > 0 {
                    push_text(tokens, &segment[..pos]);
                }
                tokens.push(Token::Placeholder(kind));
                segment = &segment[pos + pat.len()..];
            }
        }
    }
}

pub fn tokens_have_placeholder(tokens: &[Token]) -> bool {
    tokens.iter().any(|t| matches!(t, Token::Placeholder(_)))
}

#[derive(Clone, Debug)]
pub struct CommandTemplate {
    pub args: Vec<Vec<Token>>,
    pub has_placeholder: bool,
}

impl CommandTemplate {
    pub fn new(raw_args: Vec<String>) -> Self {
        let args: Vec<Vec<Token>> = raw_args.iter().map(|a| parse_template(a)).collect();
        let has_placeholder = args.iter().any(|a| tokens_have_placeholder(a));
        Self { args, has_placeholder }
    }

    fn build_arg(&self, tokens: &[Token], values: &PlaceholderValues) -> OsString {
        let mut out = OsString::new();
        for token in tokens {
            match token {
                Token::Text(text) => out.push(text),
                Token::Placeholder(kind) => out.push(values.get(*kind)),
            }
        }
        out
    }

    pub fn build_args_for_entry(&self, values: &PlaceholderValues) -> Vec<OsString> {
        let mut args: Vec<OsString> =
            self.args.iter().map(|a| self.build_arg(a, values)).collect();
        if !self.has_placeholder {
            args.push(values.path.clone());
        }
        args
    }
