    }
}

pub struct SearchPatterns;

impl SearchPatterns {
    pub fn compile(
        main_pattern: Option<String>,
        and_patterns: &[String],
        glob: bool,
        fixed_strings: bool,
        case_sensitive_flag: Option<bool>,
    ) -> Result<CompiledPatterns, String> {
        // Patterns in the order they are compiled by the reference:
        // --and patterns first, then the main pattern.
        let mut raw_patterns: Vec<String> = Vec::new();
        raw_patterns.extend(and_patterns.iter().cloned());
        if let Some(pat) = main_pattern {
            raw_patterns.push(pat);
        }

        let case_sensitive = match case_sensitive_flag {
            Some(value) => value,
            None => raw_patterns
                .iter()
                .any(|pat| pat.chars().any(|c| c.is_uppercase())),
        };

        let mut matchers: Vec<Matcher> = Vec::new();
        let mut only_hidden = false;

        for raw in &raw_patterns {
            if glob {
                if raw.is_empty() {
                    matchers.push(Matcher::All);
                    continue;
                }
                let glob_obj = GlobBuilder::new(raw)
                    .literal_separator(true)
                    .case_insensitive(!case_sensitive)
                    .build()
                    .map_err(|err| format!("[fd error]: {err}"))?;
                if !only_hidden {
                    if let Ok(hir) = regex_syntax::Parser::new().parse(glob_obj.regex()) {
                        if hir_only_hidden(&hir) {
                            only_hidden = true;
                        }
                    }
                }
                matchers.push(Matcher::Glob(glob_obj.compile_matcher()));
            } else if fixed_strings {
                let escaped = regex::escape(raw);
                let regex = regex::RegexBuilder::new(&escaped)
                    .case_insensitive(!case_sensitive)
                    .dot_matches_new_line(true)
                    .build()
                    .map_err(|err| format!("[fd error]: {err}"))?;
                matchers.push(Matcher::Regex(regex));
            } else {
                let regex = regex::RegexBuilder::new(raw)
                    .case_insensitive(!case_sensitive)
                    .dot_matches_new_line(true)
                    .build()
                    .map_err(|err| {
                        format!(
                            "[fd error]: {err}\n\nNote: You can use the '--fixed-strings' option to search for a literal string instead of a regular expression. Alternatively, you can also use the '--glob' option to match on a glob pattern."
                        )
                    })?;
                if !only_hidden {
                    if let Ok(hir) = regex_syntax::Parser::new().parse(raw) {
                        if hir_only_hidden(&hir) {
                            only_hidden = true;
                        }
                    }
                }
                matchers.push(Matcher::Regex(regex));
            }
        }

        Ok(CompiledPatterns { matchers, only_hidden })
    }
}

fn hir_only_hidden(hir: &regex_syntax::hir::Hir) -> bool {
    let HirKind::Concat(parts) = hir.kind() else {
        return false;
    };
    if parts.len() < 2 {
        return false;
    }
    if !matches!(parts[0].kind(), HirKind::Look(Look::Start)) {
        return false;
    }
    match parts[1].kind() {
        HirKind::Literal(lit) => lit.as_ref().first() == Some(&b'.'),
        HirKind::Class(Class::Unicode(cls)) => {
            let ranges = cls.ranges();
            ranges.len() == 1 && ranges[0].start() == '.' && ranges[0].end() == '.'
        }
        HirKind::Class(Class::Bytes(cls)) => {
            let ranges = cls.ranges();
            ranges.len() == 1 && ranges[0].start() == b'.' && ranges[0].end() == b'.'
        }
        _ => false,
    }
}
