fn parse_when(value: Option<&str>) -> ColorWhen {
    match value {
        Some("always") => ColorWhen::Always,
        Some("never") => ColorWhen::Never,
        _ => ColorWhen::Auto,
    }
}

fn build_file_types(matches: &clap::ArgMatches) -> Option<FileTypes> {
    let values: Vec<String> = get_string_list(matches, "type");
    if values.is_empty() {
        return None;
    }
    let mut ft = FileTypes::default();
    for value in &values {
        match value.as_str() {
            "f" | "file" => ft.files = true,
            "d" | "dir" | "directory" => ft.directories = true,
            "l" | "symlink" => ft.symlinks = true,
            "s" | "socket" => ft.sockets = true,
            "p" | "pipe" => ft.pipes = true,
            "b" | "block-device" => ft.block_devices = true,
            "c" | "char-device" => ft.char_devices = true,
            "x" | "executable" => ft.executables_only = true,
            "e" | "empty" => ft.empty_only = true,
            _ => {}
        }
    }
    if ft.executables_only {
        ft.files = true;
    }
    if ft.empty_only && !ft.files && !ft.directories {
        ft.files = true;
        ft.directories = true;
    }
    Some(ft)
}

fn global_ignore_file_path() -> Option<PathBuf> {
    let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
        Some(val) if !val.is_empty() => PathBuf::from(val),
        _ => match std::env::var_os("HOME") {
            Some(home) if !home.is_empty() => PathBuf::from(home).join(".config"),
            _ => return None,
        },
    };
    Some(config_dir.join("fd").join("ignore"))
}

struct SharedState {
    config: Config,
    patterns: CompiledPatterns,
}

fn display_path(config: &Config, entry: &EntryData) -> PathBuf {
    if config.strip_cwd_prefix {
        if let Ok(stripped) = entry.path.strip_prefix(".") {
            return stripped.to_path_buf();
        }
    }
    entry.path.clone()
}

fn run(
    config: Config,
    compiled: CompiledPatterns,
    overrides: Option<ignore::overrides::Override>,
    exec_templates: Option<Vec<CommandTemplate>>,
    exec_batch_templates: Option<Vec<CommandTemplate>>,
) -> i32 {
    let shared = Arc::new(SharedState { config, patterns: compiled });
    let config_ref = &shared.config;

    let first_path = config_ref.search_paths[0].clone();
    let mut builder = WalkBuilder::new(&first_path);
    for path in &config_ref.search_paths[1..] {
        builder.add(path);
    }
    builder
        .hidden(!config_ref.show_hidden)
        .parents(config_ref.ignore_parent)
        .ignore(!config_ref.no_ignore)
        .git_ignore(!config_ref.no_ignore && !config_ref.no_ignore_vcs)
        .git_global(!config_ref.no_ignore && !config_ref.no_ignore_vcs)
        .git_exclude(!config_ref.no_ignore && !config_ref.no_ignore_vcs)
        .require_git(config_ref.require_git)
        .follow_links(config_ref.follow)
        .max_depth(config_ref.max_depth)
        .same_file_system(config_ref.one_file_system)
        .threads(config_ref.threads)
        .add_custom_ignore_filename(".fdignore");
    if let Some(ov) = overrides {
        builder.overrides(ov);
    }
    if !config_ref.no_ignore && !config_ref.no_global_ignore_file {
        if let Some(global_path) = global_ignore_file_path() {
            if global_path.is_file() {
                if let Some(err) = builder.add_ignore(&global_path) {
                    eprintln!("[fd error]: Malformed pattern in global ignore file. {err}.");
                }
            }
        }
    }
    for ignore_file in &config_ref.ignore_files {
        if let Some(err) = builder.add_ignore(ignore_file) {
            eprintln!("[fd error]: Malformed pattern in custom ignore file. {err}.");
        }
    }

    let walker = builder.build_parallel();
    let effective_max_results: Option<usize> = if config_ref.quiet { Some(1) } else { config_ref.max_results };

    let (tx, rx) = mpsc::sync_channel::<EntryData>(1024);
    let counter = Arc::new(AtomicUsize::new(0));
    let shared_for_walker = Arc::clone(&shared);
    let counter_for_walker = Arc::clone(&counter);

    let walker_thread = std::thread::spawn(move || {
        walker.run(|| {
            let tx = tx.clone();
            let counter = Arc::clone(&counter_for_walker);
            let shared = Arc::clone(&shared_for_walker);
            Box::new(move |result| visit_entry(result, &shared, &tx, &counter, effective_max_results))
        });
    });

    let is_exec = exec_templates.is_some();
    let is_batch = exec_batch_templates.is_some() || config_ref.list_details;

    if config_ref.quiet {
        let found = rx.recv().is_ok();
        drop(rx);
        let _ = walker_thread.join();
        return if found { 0 } else { 1 };
    } else if is_exec {
        let entries: Vec<EntryData> = rx.into_iter().collect();
        let _ = walker_thread.join();
        let templates = exec_templates.unwrap();
        let separator = config_ref.path_separator.as_deref();
        let cfg = Arc::clone(&shared);
        let had_error = exec::execute_each(&templates, &entries, config_ref.threads, config_ref.print0, separator, &|entry| display_path(&cfg.config, entry));
        return if had_error { 1 } else { 0 };
    } else if is_batch {
        let entries: Vec<EntryData> = rx.into_iter().collect();
        let _ = walker_thread.join();
        let templates: Vec<CommandTemplate> = if config_ref.list_details {
            let colour = if config_ref.use_color { "--color=always" } else { "--color=never" };
            vec![CommandTemplate::new(vec!["ls".to_owned(), "-l".to_owned(), "-h".to_owned(), "-d".to_owned(), colour.to_owned()])]
        } else {
            exec_batch_templates.unwrap()
        };
        let separator = config_ref.path_separator.as_deref();
        let cfg = Arc::clone(&shared);
        let had_error = exec::execute_batch(&templates, &entries, config_ref.batch_size, separator, &|entry| display_path(&cfg.config, entry));
        return if had_error { 1 } else { 0 };
    }

    let mut exit_code = 0;
    let lscolors = if config_ref.use_color { Some(LsColors::from_env()) } else { None };
    let format_tokens: Option<Vec<exec::Token>> = config_ref.format.as_ref().map(|fmt| parse_template(fmt));
    let hostname = get_hostname();

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    let print_one = |out: &mut dyn Write, entry: &EntryData| -> std::io::Result<()> {
        let rendered = render_entry(&shared.config, entry, lscolors.as_ref(), format_tokens.as_ref(), &hostname);
        out.write_all(&rendered)?;
        if shared.config.print0 {
            out.write_all(&[0])?;
        } else {
            out.write_all(b"\n")?;
        }
        Ok(())
    };

    let max_buffer_time = config_ref.max_buffer_time;
    let mut streaming = max_buffer_time == 0;
    let start = Instant::now();
    let deadline = start + Duration::from_millis(max_buffer_time);
    let mut buffer: Vec<EntryData> = Vec::new();
    let mut write_failed = false;

    'receive: loop {
        if streaming {
            match rx.recv() {
                Ok(entry) => {
                    if print_one(&mut out, &entry).is_err() {
                        write_failed = true;
                        break 'receive;
                    }
                }
                Err(_) => break 'receive,
            }
        } else {
            let remaining = deadline.saturating_duration_since(Instant::now());
            match rx.recv_timeout(remaining) {
                Ok(entry) => {
                    buffer.push(entry);
                    if buffer.len() > 1000 {
                        for entry in buffer.drain(..) {
                            if print_one(&mut out, &entry).is_err() {
                                write_failed = true;
                                break 'receive;
                            }
                        }
                        streaming = true;
                    }
                }
                Err(mpsc::RecvTimeoutError::Timeout) => {
                    for entry in buffer.drain(..) {
                        if print_one(&mut out, &entry).is_err() {
                            write_failed = true;
                            break 'receive;
                        }
                    }
                    streaming = true;
                }
                Err(mpsc::RecvTimeoutError::Disconnected) => {
                    buffer.sort_by(|a, b| a.path.cmp(&b.path));
                    for entry in buffer.drain(..) {
                        if print_one(&mut out, &entry).is_err() {
                            write_failed = true;
                            break 'receive;
                        }
                    }
                    break 'receive;
                }
            }
        }
    }

    if out.flush().is_err() {
        write_failed = true;
    }
    drop(out);
    drop(rx);
    let _ = walker_thread.join();
    if write_failed {
        exit_code = 1;
    }
    exit_code
}

fn get_hostname() -> String {
    let mut buf = [0u8; 256];
    let result = unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if result != 0 {
        return String::new();
    }
    let len = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..len]).into_owned()
}

fn visit_entry(
    result: Result<ignore::DirEntry, ignore::Error>,
    shared: &SharedState,
    tx: &mpsc::SyncSender<EntryData>,
    counter: &AtomicUsize,
    max_results: Option<usize>,
) -> WalkState {
    let config = &shared.config;
    let entry = match result {
        Ok(entry) => entry,
        Err(err) => {
            if config.show_errors {
                eprintln!("[fd error]: {err}");
            }
            return WalkState::Continue;
        }
    };

    let depth = entry.depth();
    let path = entry.path().to_path_buf();

    if !config.ignore_contain.is_empty() && path.is_dir() {
        for name in &config.ignore_contain {
            if path.join(name).exists() {
                return WalkState::Skip;
            }
        }
    }

    if depth == 0 {
        return WalkState::Continue;
    }

    let file_type = entry.file_type();
    let is_dir = file_type.map(|ft| ft.is_dir()).unwrap_or(false);
    let metadata = entry.metadata().ok();
    let entry_data = EntryData { path: path.clone(), is_dir, metadata: metadata.clone(), file_type };

    if !entry_matches(config, &shared.patterns, &entry_data, depth) {
        return WalkState::Continue;
    }

    let count = counter.fetch_add(1, Ordering::Relaxed) + 1;
    let send_result = tx.send(entry_data);
    let reached_limit = max_results.map(|limit| count >= limit).unwrap_or(false);
    if send_result.is_err() || reached_limit {
        return WalkState::Quit;
    }
    if config.prune && is_dir {
        return WalkState::Skip;
    }
    WalkState::Continue
}

fn entry_matches(config: &Config, patterns: &CompiledPatterns, entry: &EntryData, depth: usize) -> bool {
    if let Some(min_depth) = config.min_depth {
        if depth < min_depth {
            return false;
        }
    }
    let search_str: String = if config.full_path {
        absolute_candidate(config, &entry.path)
    } else {
        entry.path.file_name().map(|name| name.to_string_lossy().into_owned()).unwrap_or_else(|| entry.path.to_string_lossy().into_owned())
    };
    if !patterns.matches(&search_str) {
        return false;
    }
    if !config.extensions.is_empty() && !matches_extension(&entry.path, &config.extensions) {
        return false;
    }
    if let Some(ft) = &config.file_types {
        if !matches_file_type(ft, entry) {
            return false;
        }
    }
    if !config.size.is_empty() {
        if !entry.path.is_file() {
            return false;
        }
        let Some(md) = &entry.metadata else { return false };
        let len = md.len();
        if !config.size.iter().all(|c| c.matches(len)) {
            return false;
        }
    }
    if config.changed_within.is_some() || config.changed_before.is_some() {
        let Some(md) = &entry.metadata else { return false };
        let Ok(modified) = md.modified() else { return false };
        if let Some(within) = config.changed_within {
            if modified <= within {
                return false;
            }
        }
        if let Some(before) = config.changed_before {
            if modified >= before {
                return false;
            }
        }
    }
    if let Some(OwnerFilter(owner)) = &config.owner {
        let Some(md) = &entry.metadata else { return false };
        if let Some(uid) = owner.uid {
            let matched = md.uid() == uid;
            if matched == owner.negate_uid {
                return false;
            }
        }
        if let Some(gid) = owner.gid {
            let matched = md.gid() == gid;
            if matched == owner.negate_gid {
                return false;
            }
        }
    }
    true
}

fn absolute_candidate(config: &Config, path: &Path) -> String {
    let absolute = to_absolute_path(config, path);
    absolute.to_string_lossy().into_owned()
}

fn to_absolute_path(config: &Config, path: &Path) -> PathBuf {
    if path.is_absolute() {
        return path.to_path_buf();
    }
    let stripped = path.strip_prefix(".").unwrap_or(path);
    match &config.current_dir {
        Some(cwd) => cwd.join(stripped),
        None => stripped.to_path_buf(),
    }
}

fn matches_extension(path: &Path, extensions: &[String]) -> bool {
    let Some(file_name) = path.file_name() else { return false };
    let mut current = PathBuf::from(file_name);
    let mut chain: Vec<String> = Vec::new();
    loop {
        let Some(ext) = current.extension() else { break };
        chain.insert(0, ext.to_string_lossy().into_owned());
        let candidate = chain.join(".").to_lowercase();
        if extensions.iter().any(|e| *e == candidate) {
            return true;
        }
        let Some(stem) = current.file_stem() else { break };
        if stem == current.as_os_str() {
            break;
        }
        current = PathBuf::from(stem);
    }
    false
}

fn is_executable_by_user(path: &Path) -> bool {
    let Ok(cpath) = std::ffi::CString::new(path.as_os_str().as_bytes()) else { return false };
    unsafe { libc::access(cpath.as_ptr(), libc::X_OK) == 0 }
}

fn matches_file_type(ft: &FileTypes, entry: &EntryData) -> bool {
    let Some(file_type) = entry.file_type else { return false };
    let basic_ok = if file_type.is_file() {
        ft.files
    } else if file_type.is_dir() {
        ft.directories
    } else if file_type.is_symlink() {
        ft.symlinks
    } else if file_type.is_socket() {
        ft.sockets
    } else if file_type.is_fifo() {
        ft.pipes
    } else if file_type.is_block_device() {
        ft.block_devices
    } else if file_type.is_char_device() {
        ft.char_devices
    } else {
        false
    };
    if !basic_ok {
        return false;
    }
    if ft.executables_only && !is_executable_by_user(&entry.path) {
        return false;
    }
    if ft.empty_only {
        if file_type.is_file() {
            let Some(md) = &entry.metadata else { return false };
            if md.len() != 0 {
                return false;
            }
        } else if file_type.is_dir() {
            let empty = std::fs::read_dir(&entry.path).map(|mut entries| entries.next().is_none()).unwrap_or(false);
            if !empty {
                return false;
            }
        } else {
            return false;
        }
    }
    true
}

fn render_entry(
    config: &Config,
    entry: &EntryData,
    lscolors: Option<&LsColors>,
    format_tokens: Option<&Vec<exec::Token>>,
    hostname: &str,
) -> Vec<u8> {
    let displayed = display_path(config, entry);
    let mut rendered: Vec<u8>;

    if let Some(tokens) = format_tokens {
        let values = PlaceholderValues::new(&displayed, config.path_separator.as_deref());
        let mut text = String::new();
        for token in tokens {
            match token {
                exec::Token::Text(t) => text.push_str(t),
                exec::Token::Placeholder(kind) => {
                    text.push_str(&values.get(*kind).to_string_lossy());
                }
            }
        }
        rendered = text.into_bytes();
    } else if let Some(colors) = lscolors {
        rendered = render_colored(config, entry, &displayed, colors);
    } else {
        rendered = Vec::new();
        let mut bytes = displayed.as_os_str().as_bytes().to_vec();
        if entry.is_dir {
            bytes.push(b'/');
        }
        if let Some(sep) = &config.path_separator {
            let text = String::from_utf8_lossy(&bytes).replace('/', sep);
            rendered.extend_from_slice(text.as_bytes());
        } else {
            rendered.extend_from_slice(&bytes);
        }
    }

    if config.use_hyperlink {
        let absolute = to_absolute_path(config, &entry.path);
        let encoded = percent_encode_path(absolute.as_os_str().as_bytes());
        let mut wrapped = Vec::new();
        wrapped.extend_from_slice(format!("\x1b]8;;file://{hostname}{encoded}\x1b\\").as_bytes());
        wrapped.extend_from_slice(&rendered);
        wrapped.extend_from_slice(b"\x1b]8;;\x1b\\");
        rendered = wrapped;
    }
    rendered
}

fn render_colored(config: &Config, entry: &EntryData, displayed: &Path, colors: &LsColors) -> Vec<u8> {
    let path_str = displayed.to_string_lossy().into_owned();
    let (parent_segment, basename_segment) = match path_str.rfind('/') {
        Some(idx) => (path_str[..=idx].to_owned(), path_str[idx + 1..].to_owned()),
        None => (String::new(), path_str.clone()),
    };
    let replace_sep = |segment: &str| -> String {
        match &config.path_separator {
            Some(sep) => segment.replace('/', sep),
            None => segment.to_owned(),
        }
    };
    let mut out = Vec::new();
    if !parent_segment.is_empty() {
        let parent_text = replace_sep(&parent_segment);
        match colors.directory_style() {
            Some(style) => out.extend_from_slice(style.paint(&parent_text).as_bytes()),
            None => out.extend_from_slice(parent_text.as_bytes()),
        }
    }
    let basename_style = colors.style_for_path(&entry.path, entry.metadata.as_ref());
    match basename_style {
        Some(style) => out.extend_from_slice(style.paint(&basename_segment).as_bytes()),
        None => out.extend_from_slice(basename_segment.as_bytes()),
    }
    if entry.is_dir {
        let slash = match &config.path_separator {
            Some(sep) => sep.clone(),
            None => "/".to_owned(),
        };
        match colors.directory_style() {
            Some(style) => out.extend_from_slice(style.paint(&slash).as_bytes()),
            None => out.extend_from_slice(slash.as_bytes()),
        }
    }
    out
}

fn percent_encode_path(bytes: &[u8]) -> String {
    let mut encoded = String::new();
    for &byte in bytes {
        let allowed = byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~' | b':' | b'/');
        if allowed {
            encoded.push(byte as char);
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    encoded
}

