root='/tmp/ext3';shutil.rmtree(root,ignore_errors=True);os.makedirs(root)
exts=[''.join(t) for t in itertools.product(string.ascii_lowercase,repeat=3)]
for e in exts:open(f'{root}/f.{e}','w').close()
env=dict(os.environ);env.pop('LS_COLORS',None)
out=subprocess.check_output(['/workspace/executable','--color','always','-t','f','.'],cwd=root,env=env)
mp={}
for raw in out.splitlines():
 m=re.match(rb'^\x1b\[([0-9;]*)m(.*)\x1b\[0m$',raw)
 if m:mp[m.group(2).decode()[2:]]=m.group(1).decode()
print(len(mp),mp)
json.dump(mp,open('/tmp/ext3_colors.json','w'))
PY"}

