import os,subprocess,shutil,re
root='/tmp/etcprobe';shutil.rmtree(root,ignore_errors=True);os.makedirs(root)
names=set()
for base in ['/etc','/usr/share/doc','/usr/share']:
 for r,d,files in os.walk(base):
  for f in files: names.add(f)
  if r.count('/')>4:d[:]=[]
created=[]
for n in names:
 if '/' in n:continue
 try:open(os.path.join(root,n),'w').close();created.append(n)
 except:pass
env=dict(os.environ);env.pop('LS_COLORS',None);out=subprocess.check_output(['/workspace/executable','-H','--color','always','-t','f','--max-depth','1','.'],cwd=root,env=env)
mp={}
for raw in out.splitlines():
 m=re.match(rb'^\x1b\[([0-9;]*)m(.*)\x1b\[0m$',raw)
 if m:mp[m.group(2).decode()]=m.group(1).decode()
# compare ours
out2=subprocess.check_output(['/tmp/newbin/executable','-H','--color','always','-t','f','--max-depth','1','.'],cwd=root,env=env);mp2={}
for raw in out2.splitlines():
 m=re.match(rb'^\x1b\[([0-9;]*)m(.*)\x1b\[0m$',raw);mp2[(m.group(2) if m else raw).decode()]=(m.group(1).decode() if m else '')
# fill
for n in created:mp2.setdefault(n,mp2.get(n,''))
diffs=[(n,mp.get(n,''),mp2.get(n,'')) for n in created if mp.get(n,'')!=mp2.get(n,'')]
print('created',len(created),'diffs',len(diffs))
for d in sorted(diffs):print(d)
PY"}

